// Blog posts batch 4 (2026-10-16): roasts, mince and Asian-style beef. Rules in posts-blog.js.
import { BLOG_KEYWORDS } from './posts-blog-keywords.js'

const meta = (slug) => ({ slug, kw: BLOG_KEYWORDS[slug].focus, keywords: BLOG_KEYWORDS[slug].keywords, date: '2026-10-16', updated: '2026-10-16' })

export const BLOG_POSTS_4 = [
  {
    ...meta('beef-donburi-recipe'),
    title: 'Beef Donburi Recipe: Japanese Beef and Onion Rice Bowl',
    seoTitle: 'Beef Donburi Recipe: Quick Japanese Rice Bowl',
    excerpt: `A beef donburi recipe for a quick Japanese rice bowl: thinly sliced beef simmered with onion in a sweet soy broth, an alcohol-free sauce and toppings.`,
    body: [
      ['p', `Beef donburi, known in Japan as gyudon, is one of the country's great comfort foods: paper-thin slices of beef and soft onion simmered in a sweet, savoury dashi and soy broth, spooned over a bowl of hot rice. It is fast food in the best sense, served in seconds at busy Tokyo counters, and it is just as quick to make at home. This beef donburi recipe takes about 20 minutes and uses a halal, alcohol-free sauce, as traditional recipes use mirin and sake.`],
      ['h2', `What is beef donburi?`],
      ['p', `Donburi simply means "bowl", and it describes any dish of rice topped with meat, fish, egg or vegetables. Beef donburi is the most famous version. The beef is sliced so thinly that it cooks in a minute or two in the simmering broth, absorbing the flavour as it goes. Restaurant chains serve it with pickled red ginger, a raw or soft egg, spring onion and a sprinkle of shichimi chilli pepper.`],
      ['h2', `Choosing and slicing the beef`],
      ['p', `Gyudon traditionally uses fatty, thinly shaved beef from the short plate or chuck, because a little fat keeps the slices tender and adds richness to the broth. Good options from our range include:`],
      ['ul', [
        `[Wagyu yakiniku slices](/product/wagyu-yakiniku-mb5/): already cut thin, richly marbled and perfect for donburi.`,
        `[Scotch fillet](/product/scotch-fillet-ribeye-steaks/): well marbled; slice it yourself very thinly.`,
        `[Rump](/product/rump-beef-steaks/): leaner but flavourful and good value.`,
        `[Beef stir-fry strips](/product/beef-stir-fry-strips/): a convenient shortcut; slice them thinner if needed.`,
      ]],
      ['p', `To slice beef thinly at home, wrap the piece in cling film and freeze it for 30 to 45 minutes until firm but not frozen solid. Use your sharpest knife to cut slices 2 mm thick or less, across the grain.`],
      ['h3', `Best beef for steak vs best beef for donburi`],
      ['p', `The best beef for steak is not always the best for a rice bowl. Lean premium cuts such as eye fillet make a superb steak but taste a little dry when shaved thin and simmered. A cut with visible marbling, such as scotch fillet or Wagyu, gives a far juicier donburi. Our guide to [scotch fillet vs porterhouse vs eye fillet](/blog/scotch-fillet-vs-porterhouse-vs-eye-fillet/) explains how the premium steaks differ.`],
      ['h2', `Beef donburi recipe`],
      ['p', `Serves two generously, or three with side dishes.`],
      ['ul', [
        `300 g thinly sliced beef`,
        `1 large brown onion, sliced into thin wedges`,
        `3/4 cup dashi (made from kombu, or use a halal-certified instant dashi)`,
        `3 tablespoons soy sauce`,
        `1 1/2 tablespoons sugar`,
        `1 tablespoon rice vinegar mixed with 1 teaspoon honey (in place of mirin)`,
        `1 teaspoon grated ginger`,
        `2 to 3 cups hot cooked Japanese short-grain rice`,
        `Toppings: pickled ginger, sliced spring onion, toasted sesame seeds, a soft-cooked or fried egg`,
      ]],
      ['h3', `Method`],
      ['p', `Combine the dashi, soy, sugar, vinegar and honey mixture and ginger in a wide frying pan and bring to a simmer. Add the onion and simmer for 4 to 5 minutes until soft and translucent. Add the beef, spreading it out in the pan and separating the slices with chopsticks. Simmer for 1 to 2 minutes, skimming off any foam, until the beef is just cooked. Do not overcook it, or it will toughen.`],
      ['p', `Divide the rice between bowls, spoon the beef and onion on top and pour over a few spoonfuls of the broth so it soaks into the rice. Top with an egg, spring onion, sesame seeds and a little pickled ginger.`],
      ['h2', `Wagyu beef donburi`],
      ['p', `Wagyu beef donburi is a luxurious version found in specialist restaurants. Because Wagyu is so richly marbled, the slices stay meltingly soft and the broth becomes rich and glossy. Use slightly less beef per bowl, as it is very rich, and balance it with plenty of pickled ginger and spring onion. Some restaurants sear the Wagyu slices briefly on a hot grill instead of simmering them, then lay them over the rice and drizzle with the reduced sauce. Explore marble scores on our [Wagyu steak](/wagyu-steak/) page.`],
      ['h2', `Making dashi at home`],
      ['p', `Dashi is the savoury broth at the heart of Japanese cooking. A simple kombu dashi needs only dried kelp and water: soak a 10 cm piece of kombu in 4 cups of cold water for at least 30 minutes, then heat it slowly and remove the kombu just before the water boils. For extra depth, add a few dried shiitake mushrooms. Many instant dashi powders contain bonito fish, which is fine in a halal kitchen, but check the label for any alcohol-based seasonings.`],
      ['h2', `Variations`],
      ['ul', [
        `Spicy: add a little chilli oil or shichimi pepper.`,
        `Curry beef bowl: stir a spoon of Japanese curry roux into the broth (see our [Japanese beef curry](/blog/japanese-beef-curry/) recipe).`,
        `Cheese gyudon: melt a slice of cheese over the hot beef, as some Japanese chains do.`,
        `With greens: add spinach or shredded cabbage to the pan in the last minute.`,
        `Chicken version (oyakodon-style): use thinly sliced chicken thigh and finish with beaten egg.`,
      ]],
      ['h2', `Beef donburi questions`],
      ['h3', `Can I make it ahead?`],
      ['p', `The beef and onion keep well in their broth for two days in the fridge. Reheat gently until just hot, and serve over freshly cooked rice.`],
      ['h3', `What rice should I use?`],
      ['p', `Japanese short-grain rice is ideal because it is slightly sticky and soaks up the broth. Medium-grain rice is a good substitute; long-grain jasmine works but gives a looser texture.`],
      ['h3', `How do I stop the beef getting tough?`],
      ['p', `Slice it very thinly, add it to a gentle simmer rather than a rolling boil, and take the pan off the heat as soon as the slices lose their pink colour.`],
      ['h3', `Is beef donburi healthy?`],
      ['p', `It is a balanced meal of protein and carbohydrate. Add a side of steamed greens or a cucumber salad, use leaner beef and reduce the sugar if you want a lighter version.`],
      ['h2', `Roast beef buy guide for leftovers`],
      ['p', `Leftover roast beef makes an excellent quick donburi: slice it thinly and warm it in the simmering broth for just 30 seconds. If you plan a roast beef buy for Sunday dinner, a [roast beef joint](/product/buy-roast-beef-online-joint/) or [topside](/product/beef-topside-whole/) will give you plenty of leftovers for rice bowls during the week. Our [roast beef cooking time](/blog/roast-beef-cooking-time/) guide covers the roast itself.`],
      ['h2', `Buy halal beef for donburi`],
      ['p', `Wagyu yakiniku, scotch fillet, rump and stir-fry strips are all in our [halal beef range](/shop/halal-beef/). Every cut is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia, with free delivery on orders over $500.`],
    ],
  },
  {
    ...meta('roast-beef-cooking-time'),
    title: 'Roast Beef Cooking Time: Charts for Every Cut and Doneness',
    seoTitle: 'Roast Beef Cooking Time: Easy Charts and Tips',
    excerpt: `Roast beef cooking time charts by weight and doneness, internal temperatures, plus how to slow cook a beef chuck roast and get perfect slices every time.`,
    body: [
      ['p', `A roast beef is one of the easiest impressive meals you can cook, as long as you get the timing right. Too short and the centre is cold and raw; too long and an expensive joint turns grey and dry. The good news is that a few simple numbers, and ideally a meat thermometer, make perfect roast beef reliable. This guide gives you roast beef cooking time charts for tender roasting joints, explains how slow cooked roast beef works for cheaper cuts, and covers seasoning, resting and carving.`],
      ['h2', `Two kinds of roast beef`],
      ['p', `Before you look at a chart, it helps to know which kind of roast you are cooking. Tender roasting cuts, such as rib roast, sirloin, eye fillet, rump and topside, are cooked like a giant steak: relatively quickly, to a pink centre. Tougher cuts with lots of connective tissue, such as chuck and blade, need long, slow, moist cooking until they are fork-tender. Applying the wrong method is the most common cause of a disappointing roast.`],
      ['h2', `Roast beef cooking time chart`],
      ['p', `For tender roasting joints, sear the beef in a hot pan first, then roast at 180°C (160°C fan). Times are per 500 g, starting from a joint that has been out of the fridge for about an hour.`],
      ['table', { caption: 'Roast beef cooking time at 180°C (per 500 g)', head: ['Doneness', 'Minutes per 500 g', 'Remove at', 'After resting'], rows: [['Rare', '15 to 18', '48°C', '52°C'], ['Medium-rare', '20 to 22', '52°C', '56°C'], ['Medium', '25 to 27', '57°C', '61°C'], ['Well done', '30 to 35', '66°C', '70°C']] }],
      ['p', `Thin, long joints such as eye fillet cook faster than thick, round joints of the same weight, so always use the temperature column as your final guide. An instant-read or leave-in probe thermometer is the single best investment for roasting.`],
      ['h3', `Best cuts for a classic roast`],
      ['ul', [
        `[Standing rib roast](/product/angus-standing-rib-roast-mb3-4/): the showpiece, juicy and full of flavour.`,
        `[Whole eye fillet](/product/whole-beef-fillet/): the most tender, cooks quickly.`,
        `[Rump](/product/beef-rump-portion/) and [rump cap](/product/beef-rump-cap/): flavourful and great value.`,
        `[Topside](/product/beef-topside-whole/): lean and economical, best served pink and thinly sliced.`,
        `[Roast beef joint](/product/buy-roast-beef-online-joint/): ready to go.`,
      ]],
      ['p', `Our guide to the [best beef cut for roasting](/blog/best-beef-cut-for-roasting/) compares them in detail.`],
      ['h2', `Seasoning: beef steak seasoning works for roasts too`],
      ['p', `A simple beef steak seasoning of coarse salt, cracked black pepper and garlic is all a good roast needs. For more flavour, rub the joint with olive oil, crushed garlic, chopped rosemary and thyme, Dijon mustard or a spice blend of paprika, cumin and coriander. Salt the joint generously at least an hour ahead, or the night before, and leave it uncovered in the fridge: the salt seasons the meat more deeply and dries the surface for a better crust.`],
      ['h2', `Beef chuck roast: low and slow`],
      ['p', `A beef chuck roast is the classic pot roast. It is full of collagen, which makes it tough if roasted quickly but gives meltingly tender, juicy meat after three or four hours of slow, moist cooking. Our [chuck steak](/product/beef-chuck-meat-steak/), [chuck tender](/product/beef-chuck-tender/) and [bolar blade](/product/beef-bolar-blade-roast/) are ideal.`],
      ['h3', `Slow cooked roast beef method`],
      ['p', `Season a 1.5 to 2 kg chuck or blade roast and brown it well on all sides in a heavy casserole. Remove it, soften a sliced onion, two carrots and two celery sticks in the pan, add garlic and a tablespoon of tomato paste, then 2 cups of beef stock and a few herbs. Return the beef, cover tightly and cook at 150°C for 3.5 to 4 hours, or on low in a slow cooker for 8 to 10 hours, until it pulls apart with a fork. Thicken the juices into gravy. Slow cooked roast beef cannot be served pink, but it makes up for it with deep flavour and a tender, shreddable texture.`],
      ['h2', `Resting and carving`],
      ['p', `Rest a roast for at least 15 minutes, and up to 30 for a large rib roast, loosely covered with foil. During resting, the internal temperature rises by 3 to 5°C and the juices settle back into the meat. Carve across the grain into thin slices with a long, sharp knife. For a rib roast, cut along the bones to remove them first, then slice the boneless joint.`],
      ['h2', `Gravy from the pan`],
      ['p', `Pour off most of the fat from the roasting tin, leaving the browned juices. Place the tin on the stove, stir in a tablespoon of flour and cook for a minute, then gradually whisk in 2 cups of beef stock. Simmer until thick, add any resting juices and season to taste.`],
      ['h2', `Roast beef questions`],
      ['h3', `Should I cover beef when roasting?`],
      ['p', `No, for tender roasting joints: leaving the roast uncovered gives a better crust. Cover slow-cooked pot roasts, which need moisture.`],
      ['h3', `How much roast beef per person?`],
      ['p', `Allow about 200 to 250 g of boneless raw beef per person, or 350 to 400 g of bone-in rib roast.`],
      ['h3', `Can I roast beef from frozen?`],
      ['p', `It is possible but not recommended, as it cooks unevenly. Thaw the joint in the fridge for 24 to 48 hours first.`],
      ['h2', `A worked example: Sunday roast for six`],
      ['p', `Say you have a 2 kg boneless rump roast and want it medium-rare for six people. Take it out of the fridge an hour before cooking and heat the oven to 180°C. Pat it dry, rub it with oil, salt, pepper and garlic, and sear it on all sides in a hot pan for about 8 minutes. At 20 to 22 minutes per 500 g, it needs roughly 80 to 90 minutes in the oven. Start checking the temperature after an hour, and remove it when the centre reads 52°C. Rest it for 20 minutes while you finish the potatoes and make the gravy; it will rise to about 56°C. Carve thinly across the grain and serve.`],
      ['p', `Planning backwards from your serving time makes the day stress-free. If dinner is at 6 pm, the roast should come out of the oven around 5.30 pm, go in around 4 pm, and come out of the fridge around 3 pm. Roast potatoes can share the oven, and vegetables can be steamed while the meat rests.`],
      ['h2', `Leftover roast beef ideas`],
      ['p', `A good roast almost always leaves something for the next day. Thinly sliced cold roast beef makes excellent sandwiches with mustard and rocket, a quick beef salad, or a topping for rice bowls. Diced leftovers can go into fried rice, a cottage pie or a quick curry. Store leftovers in a sealed container in the fridge and use them within three days, or freeze slices with a little gravy for up to two months.`],
      ['h2', `Finding a butcher for your roast`],
      ['p', `If you have been looking for a wagyu butcher near me for a special roast, Wagyu topside and rump make spectacularly rich roasts. Our [Wagyu topside roast](/product/wagyu-topside-roast-mb9/) and [whole Wagyu rump](/product/wagyu-rump-whole-mb5/) are delivered chilled across Australia. Every cut in our [halal beef range](/shop/halal-beef/) is certified halal by Halal Control Australia and delivered from Greenacre, Sydney.`],
    ],
  },
  {
    ...meta('beef-pasta-bake'),
    title: 'Beef Pasta Bake: An Easy, Cheesy Family Dinner',
    seoTitle: 'Easy Beef Pasta Bake With Beef Mince',
    excerpt: `An easy beef pasta bake for the whole family: a rich beef mince and tomato sauce, short pasta and a golden cheese topping, with make-ahead and freezing tips.`,
    body: [
      ['p', `A beef pasta bake is the definition of family comfort food. A rich, slow-simmered beef mince sauce is tossed through short pasta, topped with cheese and baked until bubbling and golden. It feeds a crowd, it is easy to make ahead, and leftovers taste even better the next day. This guide walks you through a reliable beef mince pasta bake recipe, explains how to keep it saucy rather than dry, and offers some easy variations.`],
      ['h2', `What makes a great beef and pasta bake`],
      ['p', `Three things make the difference between an ordinary beef and pasta bake and a great one. First, a well-browned, deeply flavoured meat sauce: brown the mince properly and give the sauce time to simmer. Second, pasta that is undercooked before baking, because it keeps cooking in the oven. Third, enough sauce: pasta absorbs liquid as it bakes, so the mixture should look slightly too saucy when it goes in.`],
      ['h2', `Choosing your mince`],
      ['p', `A mince with a little fat gives the best flavour. Our [premium beef mince](/product/premium-beef-mince/) has enough fat to brown beautifully and keep the sauce rich. For a lighter bake, [extra lean beef mince](/product/extra-lean-beef-mince/) works well; add a splash of olive oil when browning. For extra nutrition and flavour, try our [beef mince with 15% liver](/product/beef-mince-with-15-liver/), which melts invisibly into a tomato sauce.`],
      ['h2', `Beef mince pasta bake recipe`],
      ['p', `Serves six.`],
      ['ul', [
        `750 g beef mince`,
        `2 tablespoons olive oil`,
        `1 onion, 1 carrot and 1 celery stick, finely diced`,
        `3 cloves garlic, crushed`,
        `2 tablespoons tomato paste`,
        `2 x 400 g cans crushed tomatoes and 1 cup beef stock`,
        `1 teaspoon dried oregano, 1 teaspoon dried basil, salt and pepper`,
        `400 g short pasta such as penne, rigatoni or fusilli`,
        `1 1/2 cups grated mozzarella and 1/2 cup grated parmesan`,
      ]],
      ['h3', `Method`],
      ['p', `Heat the oil in a large, heavy pan over high heat. Add the mince in two batches and cook, breaking it up, until well browned; do not stir too often, as browning builds flavour. Remove and set aside. Reduce the heat, add the onion, carrot and celery and cook for 8 minutes until soft. Add the garlic and tomato paste and cook for 2 minutes. Return the mince, add the tomatoes, stock and herbs, and simmer for 25 to 30 minutes until rich and slightly thickened. Season well.`],
      ['p', `Meanwhile, heat the oven to 200°C. Cook the pasta in well-salted boiling water for 2 minutes less than the packet instructions; drain. Mix the pasta with the sauce and half the mozzarella and spread it into a large baking dish. Top with the remaining mozzarella and the parmesan. Bake for 20 to 25 minutes until golden and bubbling. Rest for 10 minutes before serving.`],
      ['h2', `Creamy variation`],
      ['p', `For a richer bake, make a quick white sauce: melt 40 g butter, stir in 40 g flour, cook for a minute, then whisk in 500 ml milk until thick. Season with nutmeg and a handful of parmesan. Spread it over the pasta before adding the cheese topping. It gives a lasagne-style richness without the layering.`],
      ['h2', `Seasoning ideas: beef steak rub in the sauce?`],
      ['p', `If you have a favourite beef steak rub in the pantry, a teaspoon of it in the meat sauce is a clever shortcut: smoked paprika, garlic, onion and herbs all suit a pasta bake. Other easy flavour boosts include a pinch of chilli flakes, a spoon of pesto stirred through before baking, or chopped olives and capers for a puttanesca twist.`],
      ['h2', `Hiding more vegetables`],
      ['p', `A pasta bake is an easy way to add vegetables for fussy eaters. Grate zucchini or carrot into the sauce, stir in a handful of spinach before baking, or add diced capsicum and mushrooms with the onion. They melt into the sauce and add sweetness and moisture.`],
      ['h2', `Making ahead and freezing`],
      ['ul', [
        `Make ahead: assemble the bake, cover and refrigerate for up to 24 hours. Add 10 minutes to the baking time.`,
        `Freeze unbaked: assemble in a freezer-safe dish, wrap well and freeze for up to 3 months. Thaw overnight in the fridge before baking.`,
        `Freeze leftovers: portion cooled bake into containers and freeze for up to 3 months.`,
        `Reheat: cover with foil and bake at 180°C for 20 to 25 minutes, or microwave single portions.`,
      ]],
      ['h2', `Beef pasta bake questions`],
      ['h3', `Why is my pasta bake dry?`],
      ['p', `There was not enough sauce, or the pasta was fully cooked before baking. Use plenty of sauce and undercook the pasta by two minutes.`],
      ['h3', `Can I use leftover bolognese?`],
      ['p', `Absolutely. Leftover bolognese makes a perfect pasta bake; loosen it with a splash of stock or water before mixing with the pasta.`],
      ['h3', `Which cheese is best?`],
      ['p', `Mozzarella melts and stretches, cheddar adds sharpness and colour, and parmesan gives a savoury, golden crust. A mix of all three is hard to beat.`],
      ['h2', `A special-occasion upgrade`],
      ['p', `For a celebration, swap the mince for slow-cooked shredded Wagyu or beef cheeks and finish with plenty of parmesan. For this kind of luxurious ragu, a Wagyu beef buy of a slow-cooking cut is the best value: our [Wagyu brisket](/product/wagyu-beef-brisket-mb9/) and [Wagyu chuck](/product/wagyu-chuck-steak-mb5/) slow cook beautifully. Our [pulled beef recipe](/blog/pulled-beef-recipe/) explains the slow-cooking method.`],
      ['h2', `Which pasta shape works best?`],
      ['p', `Short, sturdy shapes with ridges or tubes hold sauce best and survive baking without turning mushy. Penne and rigatoni are classics because the sauce fills their tubes. Fusilli traps sauce in its spirals, and conchiglie (shells) cup little pockets of meat and cheese. Avoid long, thin pasta such as spaghetti, which tangles and dries out at the edges. Whatever shape you choose, cook it two minutes short of the packet time so it finishes softening in the oven.`],
      ['h2', `Serving a pasta bake`],
      ['p', `A rich, cheesy pasta bake needs something fresh alongside. A crisp green salad with a lemony dressing, steamed broccoli or green beans, or a tomato and cucumber salad all balance the richness. Garlic bread is a popular extra for hungry teenagers. Rest the bake for ten minutes before cutting so the sauce sets slightly and the portions hold their shape on the plate.`],
      ['h2', `Buy halal beef mince online`],
      ['p', `Premium, extra lean and liver-enriched mince are all in our [halal beef range](/shop/halal-beef/), and our [beef mince carton](/product/beef-mince-carton/) suits families and caterers. Everything is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide. Looking for more mince ideas? See our [30 minute beef mince recipes](/blog/30-minute-beef-mince-recipes/).`],
    ],
  },
  {
    ...meta('japanese-beef-curry'),
    title: 'Japanese Beef Curry: A Rich, Mild Curry Rice Recipe',
    seoTitle: 'Japanese Beef Curry Recipe: Easy and Tender',
    excerpt: `A Japanese beef curry recipe made from scratch: a mild, thick, slightly sweet roux, tender beef, potato and carrot, served over short-grain rice.`,
    body: [
      ['p', `Japanese curry is unlike any other curry you have tried. It is thick, glossy and mild, with a gentle sweetness from grated apple and honey, and it is served over a mound of sticky rice. It is one of Japan's most popular home-cooked meals, eaten by children and adults alike, and it is easy to make. This Japanese beef curry recipe shows you how to make the curry roux from scratch, so you control the ingredients and avoid the additives in some packet blocks.`],
      ['h2', `A short history of Japanese curry`],
      ['p', `Curry arrived in Japan in the late 1800s via the British Navy, which had adopted it from India. The Japanese adapted it into a thick stew with a flour-based roux, closer to a European gravy than an Indian curry, and it became a staple of school lunches and military mess halls. Today kare raisu (curry rice) is considered a national dish, and every family has its favourite version.`],
      ['h2', `Choosing the beef`],
      ['p', `Japanese curry simmers for 1.5 to 2 hours, so it needs a cut that becomes tender with time. [Chuck steak](/product/beef-chuck-meat-steak/) is the classic choice. [Gravy beef](/product/gravy-beef/) gives a silkier sauce, and [beef cheeks](/product/buy-beef-cheeks/) make an indulgent version. For a quick curry, some cooks use thinly sliced beef such as our [Wagyu yakiniku](/product/wagyu-yakiniku-mb5/), added in the last 10 minutes. Cut slow-cooking beef into 3 to 4 cm chunks.`],
      ['h2', `Japanese beef curry recipe`],
      ['p', `Serves six.`],
      ['h3', `Curry`],
      ['ul', [
        `1 kg chuck steak, cut into 3 to 4 cm pieces`,
        `2 tablespoons oil`,
        `2 large onions, thinly sliced`,
        `2 carrots, cut into chunks`,
        `3 potatoes, peeled and cut into large chunks`,
        `1 apple, peeled and grated`,
        `1 litre beef or chicken stock`,
        `1 tablespoon honey, 2 tablespoons soy sauce and 1 tablespoon tomato sauce`,
      ]],
      ['h3', `Homemade curry roux`],
      ['ul', [
        `60 g butter`,
        `5 tablespoons plain flour`,
        `2 tablespoons mild curry powder`,
        `1 teaspoon garam masala`,
        `1/2 teaspoon each ground cumin and ground coriander`,
        `1/4 teaspoon cayenne pepper (optional, for heat)`,
      ]],
      ['h3', `Method`],
      ['p', `Heat the oil in a large pot and brown the beef in batches; set aside. Add the onions and a pinch of salt and cook slowly over medium-low heat for 20 to 25 minutes until deep golden and sweet. This caramelised onion is the secret to a rich Japanese curry. Return the beef, add the stock, grated apple, honey, soy and tomato sauce, bring to a simmer, cover and cook for 1 hour 15 minutes.`],
      ['p', `Add the carrots and potatoes and simmer for 25 to 30 minutes more, until the vegetables and beef are tender. Meanwhile make the roux: melt the butter in a small pan, stir in the flour and cook over low heat, stirring, for 8 to 10 minutes until it turns a light caramel colour. Add the spices and cook for 1 minute more. Remove from the heat.`],
      ['p', `Ladle a cup of hot liquid from the curry into the roux and whisk until smooth, then stir the mixture back into the pot. Simmer gently for 5 to 10 minutes, stirring, until thick and glossy. Taste and adjust with salt, a little more honey or soy.`],
      ['h2', `Japanese curry recipe beef tips`],
      ['ul', [
        `Caramelise the onions slowly: they give the curry its body and sweetness.`,
        `Toast the roux until golden for a deeper, nutty flavour.`,
        `Grated apple or a spoon of honey adds the gentle sweetness Japanese curry is known for.`,
        `A square of dark chocolate or a teaspoon of instant coffee adds depth, a common Japanese home trick.`,
        `Rest the curry overnight: like most stews, it tastes even better the next day.`,
      ]],
      ['h2', `Serving Japanese curry`],
      ['p', `Serve over Japanese short-grain rice with fukujinzuke (sweet pickled vegetables) or pickled ginger on the side. For katsu curry, serve the curry sauce over rice with a crumbed, fried cutlet: our [beef schnitzel](/blog/beef-schnitzel/) or [how to crumb chicken](/blog/how-to-crumb-chicken/) guides show how. Curry udon, with the sauce thinned with stock and poured over noodles, is another favourite.`],
      ['h2', `Grill night: beef master BBQ ideas`],
      ['p', `Japanese families often pair curry nights with grilled skewers or yakiniku. If you see yourself as a beef master BBQ cook, try grilling thin slices of marbled beef quickly over very high heat and serving them with a soy and sesame dipping sauce alongside the curry. Our [beef skewers](/blog/beef-skewers/) guide has more ideas.`],
      ['h2', `Wagyu beef prices and when to splurge`],
      ['p', `Wagyu beef prices vary widely by cut and marble score, and for a slow-cooked curry you do not need the most expensive steaks. Wagyu chuck or brisket gives rich, melting results for much less than premium Wagyu steaks. Save high-marble Wagyu for quick cooking, where its texture shines. Our [Wagyu steak](/wagyu-steak/) page explains the cuts and marble scores, and every product page shows its price per kilo.`],
      ['h2', `Japanese beef curry questions`],
      ['h3', `Is Japanese curry spicy?`],
      ['p', `It is usually mild and slightly sweet. You can make it hotter by adding cayenne or chilli to the roux.`],
      ['h3', `Can I use a packet curry block?`],
      ['p', `Yes, but read the label: some brands contain ingredients from non-halal sources, such as pork extract or lard. Making your own roux, as above, avoids this.`],
      ['h3', `Does it freeze well?`],
      ['p', `The sauce and beef freeze well for three months. Potatoes can turn grainy, so you can leave them out when freezing and add freshly boiled potatoes when reheating.`],
      ['h2', `Toppings for Japanese curry`],
      ['p', `Part of the fun of Japanese curry is customising each bowl. Popular toppings include a soft-boiled or fried egg, grated cheese melted over the hot curry, pickled red ginger, fukujinzuke relish, sliced spring onion, crispy fried onions and a crumbed cutlet for katsu curry. In Japan, many people also add a spoon of natto or a slice of fried eggplant. Set out a few bowls of toppings and let everyone build their own plate.`],
      ['p', `For a vegetable-packed version, add pumpkin, eggplant or green beans with the potatoes. Kabocha pumpkin is especially popular in Japan and melts slightly into the sauce, making it even thicker and sweeter.`],
      ['h2', `Buy halal beef for Japanese curry`],
      ['p', `Chuck, gravy beef, cheeks and Wagyu yakiniku are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('mongolian-beef-slow-cooker'),
    title: 'Mongolian Beef Slow Cooker Recipe: Sticky and Tender',
    seoTitle: 'Easy Mongolian Beef Slow Cooker Recipe',
    excerpt: `A Mongolian beef slow cooker recipe: tender beef in a sticky soy, garlic and ginger sauce, with crock pot timings and a quick stovetop method.`,
    body: [
      ['p', `Mongolian beef is a takeaway favourite: tender beef in a sticky, glossy sauce of soy, brown sugar, garlic and ginger, finished with spring onions. Despite the name, it is a Chinese-American and Chinese-Australian restaurant dish rather than a Mongolian one. This Mongolian beef slow cooker recipe gives you all of that flavour with almost no hands-on work: the slow cooker turns an economical cut into melt-in-the-mouth beef while you get on with your day.`],
      ['h2', `Why make Mongolian beef in a slow cooker?`],
      ['p', `Restaurant Mongolian beef uses thin slices of tender steak, coated in cornflour and flash-fried. That gives great texture but requires a very hot wok and quick work. The slow cooker version uses a cheaper, harder-working cut that becomes meltingly tender over several hours, and the sauce thickens at the end. It is ideal for busy weeknights: prepare it in the morning and dinner is ready when you get home.`],
      ['h2', `Choosing the beef`],
      ['p', `For slow cooker Mongolian beef, choose a cut that stays juicy over a long cook:`],
      ['ul', [
        `[Chuck steak](/product/beef-chuck-meat-steak/): our top pick; tender and flavourful after slow cooking.`,
        `[Chuck tender](/product/beef-chuck-tender/): a little leaner but still slow cooks well.`,
        `[Flank steak](/product/flank-steak-beef/): the traditional restaurant cut; slices neatly but can dry out if cooked too long.`,
        `[Gravy beef](/product/gravy-beef/): very tender and rich.`,
      ]],
      ['p', `Slice the beef into strips about 1 cm thick and 5 cm long, cutting across the grain.`],
      ['h2', `Mongolian beef slow cooker recipe`],
      ['p', `Serves four to five.`],
      ['ul', [
        `1 kg chuck steak, sliced into strips`,
        `1/4 cup cornflour`,
        `1 tablespoon oil`,
        `4 cloves garlic, crushed, and 1 tablespoon grated ginger`,
        `1/2 cup soy sauce (salt-reduced if you prefer)`,
        `1/2 cup brown sugar`,
        `1/2 cup water`,
        `1 tablespoon hoisin sauce and 1 teaspoon sesame oil`,
        `1/2 teaspoon chilli flakes (optional)`,
        `4 spring onions, cut into 4 cm lengths, and sesame seeds to serve`,
      ]],
      ['h3', `Method`],
      ['p', `Toss the beef strips in the cornflour until evenly coated. For the best flavour, heat the oil in a frying pan and brown the beef quickly in batches; this step is optional but adds colour and depth. Place the beef in the slow cooker.`],
      ['p', `Whisk together the garlic, ginger, soy sauce, brown sugar, water, hoisin, sesame oil and chilli flakes, and pour over the beef. Stir to coat. Cook on low for 4 to 5 hours, or on high for 2.5 to 3 hours, until the beef is tender. Stir in the spring onions for the last 15 minutes. If the sauce needs thickening, mix a teaspoon of cornflour with a tablespoon of water, stir it in and cook on high, uncovered, for 15 minutes. Serve over rice, scattered with sesame seeds.`],
      ['h2', `Mongolian beef crock pot timings`],
      ['p', `Every slow cooker is a little different. In a Mongolian beef crock pot recipe, strips of chuck are usually tender after 4 hours on low; if yours runs hot, check from 3.5 hours. Unlike a whole roast, sliced beef can overcook and turn stringy, so do not leave it for 8 to 10 hours. If you are out all day, use larger chunks of chuck (about 4 cm) and shred them at the end instead.`],
      ['h2', `Quick stovetop version`],
      ['p', `Short on time? Slice 600 g of rump or flank very thinly, toss in cornflour and shallow-fry in batches in hot oil for 1 to 2 minutes until crisp. Drain. Simmer the sauce ingredients in a clean pan for 3 to 4 minutes until syrupy, add the beef and spring onions and toss for 30 seconds. This gives the crisp, restaurant-style texture in about 25 minutes.`],
      ['h2', `What to serve with Mongolian beef`],
      ['ul', [
        `Steamed jasmine rice or egg fried rice (see our [fried rice and beef](/blog/fried-rice-and-beef/) recipe)`,
        `Steamed broccoli or Chinese greens with garlic`,
        `Crispy fried rice noodles`,
        `A crunchy cucumber and sesame salad`,
      ]],
      ['h2', `Using a brisket beef rub for a twist`],
      ['p', `If you have a brisket beef rub in the pantry, a teaspoon in the sauce gives an unexpected smoky depth. Smoked paprika, garlic and pepper all pair well with soy and brown sugar. Our [beef brisket rub](/blog/beef-brisket-rub/) guide has three rub recipes to try.`],
      ['h2', `Mongolian beef questions`],
      ['h3', `Is Mongolian beef spicy?`],
      ['p', `Traditionally it is mild and sweet, with only a little chilli. Add more chilli flakes or fresh chilli if you like heat.`],
      ['h3', `Can I freeze it?`],
      ['p', `Yes. Cool it quickly and freeze in portions for up to three months. Reheat gently and add fresh spring onion before serving.`],
      ['h3', `How do I make it less sweet?`],
      ['p', `Reduce the brown sugar to a quarter cup and add a squeeze of lime juice at the end.`],
      ['h2', `Wagyu beef price per kg and upgrades`],
      ['p', `For a special occasion, Wagyu chuck makes an incredibly rich slow cooker Mongolian beef. The Wagyu beef price per kg is higher than regular beef, but a slow-cooking Wagyu cut such as our [Wagyu chuck steak](/product/wagyu-chuck-steak-mb5/) costs much less than premium Wagyu steaks and gives a luxurious result. Compare prices on each product page.`],
      ['h2', `Preparing ahead for a busy day`],
      ['p', `The night before, slice the beef and keep it covered in the fridge, and mix the sauce in a jar. In the morning, toss the beef in cornflour, brown it quickly if you have time, and put everything in the slow cooker. If your slow cooker has a keep-warm setting, it will switch over automatically when the cooking time ends; otherwise, set a timer so the beef does not overcook. When you get home, cook a pot of rice, steam some greens and stir in the spring onions. Dinner is on the table in 20 minutes.`],
      ['p', `Leftovers keep well for three days in the fridge. Reheat them gently in a pan or microwave, adding a splash of water if the sauce has thickened.`],
      ['p', `You can also double the recipe and freeze half in flat bags. Thaw overnight in the fridge and reheat on the stove for an almost instant takeaway-style dinner on a busy night.`],
      ['h2', `Buy halal beef online`],
      ['p', `Chuck, flank, gravy beef and Wagyu are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('beef-meat-patties-recipe'),
    title: 'Beef Meat Patties Recipe: Juicy Burgers Every Time',
    seoTitle: 'Beef Meat Patties Recipe: Juicy and Easy',
    excerpt: `A beef meat patties recipe for juicy burgers: the right mince and fat ratio, shaping, seasoning, grilling times, and the best halal cuts to grind your own.`,
    body: [
      ['p', `A great burger is all about the patty. Juicy, well seasoned and charred on the outside, it is the difference between a forgettable fast-food burger and one you will make again and again. This beef meat patties recipe covers everything you need: choosing the mince, the ideal fat ratio, shaping and seasoning, cooking on the grill or in a pan, and how to keep patties juicy. It also explains which cuts to grind if you want to make your own blend.`],
      ['h2', `Choosing the mince`],
      ['p', `Fat is flavour, and in a burger it is also moisture. The ideal mince for patties contains about 15 to 20% fat. Too lean, and the patty is dry and crumbly; too fatty, and it shrinks dramatically and flares up on the grill. Our [premium beef mince](/product/premium-beef-mince/) is a good balance for burgers. If you prefer leaner patties, [extra lean beef mince](/product/extra-lean-beef-mince/) works best with a binder such as egg and breadcrumbs.`],
      ['p', `If you want the easiest option, our ready-made [beef patties made from chuck and brisket](/product/beef-patties-chuck-and-brisket/) go straight onto the grill.`],
      ['h3', `Grinding your own blend`],
      ['p', `Many burger lovers grind their own blend for the best flavour. Chuck is the classic burger cut, with a natural fat ratio of about 15 to 20%. Brisket adds rich, beefy flavour, and short rib adds luxurious fat. A popular blend is two parts chuck to one part brisket. Interestingly, the best cut for pulled beef, chuck, is also the best for burgers, for the same reason: it has plenty of flavour and fat.`],
      ['h2', `Beef patties recipe: classic smashed and thick-style`],
      ['p', `This beef patties recipe makes six generous patties.`],
      ['ul', [
        `1 kg beef mince (15 to 20% fat)`,
        `1 1/2 teaspoons salt (added just before cooking)`,
        `1 teaspoon freshly ground black pepper`,
        `1/2 teaspoon garlic powder and 1/2 teaspoon onion powder (optional)`,
      ]],
      ['p', `Keep the mince cold. Divide it into six equal portions of about 165 g. Gently shape each into a loose ball, then flatten into a patty about 2 cm thick and 1 cm wider than your burger bun, as patties shrink when cooked. Press a shallow dimple into the centre of each with your thumb; this stops the patty puffing up into a dome. Refrigerate the shaped patties for 20 minutes to firm up.`],
      ['h3', `Recipe for patties beef lovers swear by: the smash burger`],
      ['p', `For smash burgers, divide the mince into 80 to 100 g balls instead. Heat a cast iron pan or flat plate until smoking hot. Place a ball on the hot surface and immediately smash it flat with a heavy spatula, pressing firmly for 10 seconds. Season the top with salt and pepper. Cook for 2 minutes until the edges are deeply browned and crisp, flip, add a slice of cheese and cook for 30 seconds more. Two thin smash patties per bun make an outstanding burger.`],
      ['h2', `Cooking the patties`],
      ['p', `Season the patties with salt and pepper on both sides just before cooking; salting the mince too early draws out moisture and makes the patties dense and sausage-like.`],
      ['ul', [
        `Barbecue or grill: heat to high, oil the grill bars, cook 2 cm patties for 4 to 5 minutes a side.`,
        `Frying pan: heat a heavy pan with a little oil over medium-high heat and cook for 4 to 5 minutes a side.`,
        `Flip only once and resist pressing down on thick patties, which squeezes out the juices.`,
      ]],
      ['p', `Minced beef should be cooked through. Food safety authorities recommend 71 to 75°C in the centre, as any bacteria on the surface of the meat are mixed throughout during mincing.`],
      ['h2', `Seasoning ideas`],
      ['ul', [
        `Classic: salt, pepper and a little garlic powder.`,
        `Middle Eastern: grated onion, parsley, cumin, allspice and sumac.`,
        `Spicy: chilli flakes, smoked paprika and chopped jalapeño.`,
        `Asian: soy sauce, ginger, garlic and spring onion (add a little breadcrumb to bind).`,
        `Herby: fresh parsley, oregano and lemon zest.`,
      ]],
      ['h2', `Building the perfect burger`],
      ['p', `Toast the buns lightly in a hot pan with a little butter. Layer from the bottom: sauce, lettuce, patty with cheese, tomato, onion, pickles, more sauce and the top bun. The lettuce under the patty stops the juices soaking the bottom bun. Serve with chips or a fresh slaw.`],
      ['h2', `Wagyu meat for sale for premium burgers`],
      ['p', `For a premium burger night, look for Wagyu meat for sale from a supplier you trust. Wagyu's marbling makes incredibly juicy patties. Grind Wagyu chuck or brisket, or mix it 50:50 with regular chuck for a more affordable but still luxurious blend. Our [Wagyu chuck](/product/wagyu-chuck-steak-mb5/) and [Wagyu brisket](/product/wagyu-beef-brisket-mb9/) are ideal, and you can explore the range on our [Wagyu steak](/wagyu-steak/) page.`],
      ['h2', `Making ahead and freezing`],
      ['p', `Shape the patties, separate them with squares of baking paper and freeze flat on a tray, then transfer to a freezer bag for up to three months. Cook from frozen over medium heat, adding a few minutes per side, or thaw overnight in the fridge.`],
      ['h2', `Beef patties questions`],
      ['h3', `Do I need egg and breadcrumbs?`],
      ['p', `Not for a classic burger with 15 to 20% fat mince. Egg and breadcrumbs are useful binders for very lean mince or for patties with lots of added ingredients.`],
      ['h3', `Why do my patties shrink?`],
      ['p', `All patties shrink as fat renders and proteins contract. Make them slightly wider than the bun and press a dimple into the centre.`],
      ['h3', `Can I make patties with lamb or camel?`],
      ['p', `Yes. Lamb mince makes rich, juicy burgers, and camel mince makes lean, flavourful patties; see our [camel burgers](/blog/camel-burgers/) guide.`],
      ['h2', `Sauces that make a burger`],
      ['p', `A good burger sauce ties everything together. For a classic burger sauce, mix mayonnaise with a little tomato sauce, mustard, finely chopped pickles and a pinch of paprika. Garlic aioli, chipotle mayonnaise, barbecue sauce and a spicy harissa yoghurt are all great alternatives. Caramelised onions, cooked slowly in butter for 20 minutes, add sweetness and depth to any burger.`],
      ['p', `Finally, rest cooked patties for a minute or two before building the burger, so the juices settle and do not soak the bun.`],
      ['h2', `Buy halal beef mince and patties`],
      ['p', `Premium mince, extra lean mince and ready-made beef patties are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, Australia-wide.`],
    ],
  },
  {
    ...meta('beef-croquettes'),
    title: 'Beef Croquettes: A Crisp, Creamy Recipe From Leftovers',
    seoTitle: 'Easy Beef Croquettes Recipe: Crisp and Creamy',
    excerpt: `How to make beef croquettes: a creamy potato or béchamel filling with slow-cooked beef, crumbed and fried golden, plus the best halal cuts to use.`,
    body: [
      ['p', `A beef croquette is a little parcel of joy: a crisp, golden crumb shell around a soft, savoury filling of tender beef and creamy potato or béchamel. Croquettes are loved across the world, from Spanish tapas bars and Dutch snack counters to Japanese korokke shops, and they are a brilliant way to turn leftover roast or slow-cooked beef into something new. This guide gives you a reliable beef croquette recipe, two styles of filling and tips for perfect frying.`],
      ['h2', `Two styles of beef croquettes`],
      ['p', `There are two main styles of beef croquettes. Potato-based croquettes, like Japanese korokke, mix mashed potato with minced or shredded beef and onion. They are sturdy, easy to shape and great for beginners. Béchamel-based croquettes, like Dutch kroketten and Spanish croquetas, use a thick white sauce to bind finely chopped meat. They have a molten, creamy centre but need chilling before shaping. Both are delicious.`],
      ['h2', `Choosing the beef`],
      ['p', `Croquettes are perfect for slow-cooked beef that shreds easily. The best cut of beef for pulled beef is also the best for croquettes: chuck, brisket or cheeks, cooked until tender. Our [chuck steak](/product/beef-chuck-meat-steak/), [point end brisket](/product/beef-point-end-brisket/) and [beef cheeks](/product/buy-beef-cheeks/) are ideal. Leftover roast beef or pot roast works beautifully too. For the potato style, browned [beef mince](/product/premium-beef-mince/) is quick and easy.`],
      ['h2', `Beef croquette recipe: potato style`],
      ['p', `Makes about 16 croquettes.`],
      ['ul', [
        `800 g floury potatoes, peeled and quartered`,
        `400 g beef mince, or 300 g shredded cooked beef`,
        `1 onion, finely diced`,
        `1 tablespoon soy sauce and 1 teaspoon sugar (for a Japanese style), or 1 teaspoon smoked paprika (for a European style)`,
        `Salt, pepper and a pinch of nutmeg`,
        `Plain flour, 2 beaten eggs and 2 cups panko breadcrumbs, for coating`,
        `Oil for frying`,
      ]],
      ['p', `Boil the potatoes until tender, drain well and mash until smooth. Brown the mince with the onion in a little oil until cooked through (or fry the onion and add the shredded beef), season with soy and sugar or paprika, and drain off any excess fat. Mix the beef into the mashed potato, season well and let it cool completely.`],
      ['p', `Shape into oval patties or logs about 6 cm long. Roll each in flour, dip in egg and press into the panko. Chill for 20 minutes. Heat oil in a deep pan to 175°C and fry in batches for 3 to 4 minutes, turning, until deep golden. Drain on a rack.`],
      ['h2', `Béchamel-style beef croquettes`],
      ['p', `Melt 60 g butter in a saucepan, add a finely chopped small onion and cook until soft. Stir in 70 g flour and cook for 2 minutes. Gradually whisk in 400 ml warm milk mixed with 100 ml beef stock, and cook, stirring, until very thick, about 8 minutes. Stir in 300 g finely chopped slow-cooked beef, chopped parsley, salt, pepper and nutmeg. Spread in a dish, cover the surface with cling film and refrigerate for at least 4 hours or overnight until firm.`],
      ['p', `With wet hands, shape tablespoons of the mixture into small logs. Coat in flour, egg and fine breadcrumbs, then repeat the egg and breadcrumb layers for a sturdy shell that will not burst. Fry at 180°C for 2 to 3 minutes until golden.`],
      ['h2', `Tips for perfect croquettes`],
      ['ul', [
        `Cool the filling completely before shaping; warm filling is soft and hard to handle.`,
        `A double coat of egg and crumbs helps prevent bursting.`,
        `Keep the oil at a steady 175 to 180°C; too cool and they absorb oil, too hot and they brown before heating through.`,
        `Fry in small batches so the temperature does not drop.`,
        `For a lighter option, spray with oil and air fry at 200°C for 10 to 12 minutes.`,
      ]],
      ['h2', `Serving ideas`],
      ['p', `Serve croquettes hot with mustard, tonkatsu sauce, aioli or a squeeze of lemon. In Japan, korokke are eaten with shredded cabbage and rice; in the Netherlands, kroketten are served on a bread roll with mustard. They also make great party food and lunchbox treats.`],
      ['h2', `Beef croquettes where to buy vs make at home`],
      ['p', `If you have been searching beef croquettes where to buy them, you will find frozen versions in some delis and Asian grocers, but homemade croquettes taste far better and you know exactly what is in them. They freeze brilliantly too: freeze crumbed, uncooked croquettes on a tray, then bag them for up to three months and fry from frozen, adding a minute or two.`],
      ['h2', `Certified Angus beef prices and premium fillings`],
      ['p', `For a special-occasion croquette, slow-cook a premium cut such as Angus brisket or Wagyu. Certified Angus beef prices are higher than standard beef, but because croquettes use a small amount of meat, a little goes a long way. Our [Angus beef range](/shop/halal-beef/) and [Wagyu brisket](/product/wagyu-beef-brisket-mb9/) make extraordinary fillings.`],
      ['h2', `Beef croquettes questions`],
      ['h3', `Why did my croquettes burst?`],
      ['p', `The filling was too soft or warm, the coating had gaps, or the oil was too hot. Chill well, double-coat and fry at 175 to 180°C.`],
      ['h3', `Can I bake them?`],
      ['p', `Yes. Spray generously with oil and bake at 220°C for 15 to 20 minutes, turning once. They will be less crisp than fried croquettes but still delicious.`],
      ['h2', `Croquettes for a party`],
      ['p', `Croquettes are perfect party food because you can prepare them days in advance. Shape and crumb them, freeze them on trays, and fry them straight from the freezer as guests arrive. Make them bite-sized for canapés, about the size of a walnut, and serve them with a couple of dipping sauces such as aioli, sweet chilli and a tangy tomato relish. Allow three to four small croquettes per person if there are other snacks, or six for a main nibble.`],
      ['p', `To keep a big batch hot, place fried croquettes on a rack over a tray in a 120°C oven for up to 20 minutes. Do not cover them, or the crumb will soften.`],
      ['p', `Leftover fried croquettes reheat well in an air fryer or oven at 200°C for 6 to 8 minutes.`],
      ['h2', `Buy halal beef online`],
      ['p', `Chuck, brisket, cheeks and mince are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia. Our [braised beef](/blog/braised-beef/) guide shows how to slow-cook the filling.`],
    ],
  },
  {
    ...meta('beef-and-lemongrass'),
    title: 'Beef and Lemongrass: Vietnamese Stir-Fry and Grilled Beef',
    seoTitle: 'Beef and Lemongrass Recipe: Quick and Fresh',
    excerpt: `Beef and lemongrass, Vietnamese style: a fragrant stir-fry, grilled lemongrass beef for noodle bowls, the best halal cuts and how to prepare lemongrass.`,
    body: [
      ['p', `Beef and lemongrass is one of the most fragrant pairings in South-East Asian cooking. In Vietnam, thin slices of beef are marinated with finely chopped lemongrass, garlic, fish sauce and a little sugar, then stir-fried or grilled over charcoal until caramelised and smoky. The result is bright, savoury and aromatic, and it takes only minutes to cook. This guide gives you a lemongrass beef stir-fry, a grilled version for noodle bowls, and tips for preparing lemongrass at home.`],
      ['h2', `Preparing lemongrass`],
      ['p', `Lemongrass has a tough, fibrous outer layer and a tender core. Trim off the root end and the dry, grassy top, leaving the bottom 10 to 12 cm. Peel away the two or three outer layers until you reach the pale, tender centre. Slice it very thinly, then chop it finely; the finer it is, the more it releases its citrusy fragrance and the less chewy it is. A food processor or mortar and pestle helps. Lemongrass freezes well, so buy a bundle and freeze any extra, whole or chopped.`],
      ['h2', `Choosing the beef`],
      ['p', `Use a tender cut sliced thinly across the grain:`],
      ['ul', [
        `[Rump](/product/rump-beef-steaks/): flavourful and good value.`,
        `[Flank](/product/flank-steak-beef/): soaks up the marinade beautifully.`,
        `[Scotch fillet](/product/scotch-fillet-ribeye-steaks/): marbled and juicy, perfect for grilling.`,
        `[Beef stir-fry strips](/product/beef-stir-fry-strips/): ready to cook.`,
      ]],
      ['h3', `Beef chuck roll for a slow-cooked twist`],
      ['p', `If you prefer a slow-cooked dish, a beef chuck roll braised with lemongrass, star anise and coconut water makes a fragrant Vietnamese-style stew similar to bò kho. Chuck becomes meltingly tender after two hours, and the lemongrass perfumes the whole pot. Our [chuck steak](/product/beef-chuck-meat-steak/) and [chuck tender](/product/beef-chuck-tender/) work well for this.`],
      ['h2', `Lemongrass beef stir-fry`],
      ['p', `Serves four with rice.`],
      ['ul', [
        `600 g rump or flank, thinly sliced across the grain`,
        `3 stalks lemongrass, finely chopped`,
        `4 cloves garlic and 2 shallots, finely chopped`,
        `1 to 2 red chillies, sliced`,
        `2 tablespoons fish sauce and 1 tablespoon soy sauce`,
        `1 tablespoon brown sugar and 1 teaspoon cracked black pepper`,
        `1 onion, cut into wedges, and a handful of green beans or snow peas`,
        `Fresh coriander, Thai basil and crushed peanuts to serve`,
      ]],
      ['h3', `Method`],
      ['p', `Mix the beef with half the lemongrass and garlic, the fish sauce, soy, sugar and pepper, and marinate for 20 to 60 minutes. Heat a wok until smoking hot, add a tablespoon of oil and stir-fry the beef in batches for 1 to 2 minutes until browned. Remove. Add a little more oil, then the remaining lemongrass, garlic, shallots and chilli, and stir-fry for 30 seconds until fragrant. Add the onion and beans and stir-fry for 2 minutes. Return the beef, toss for 30 seconds, and finish with herbs and peanuts.`],
      ['h2', `Beef with lemongrass recipe for noodle bowls`],
      ['p', `This grilled beef with lemongrass recipe is the classic topping for bún bò xào, a Vietnamese vermicelli noodle salad. Marinate thin slices of scotch fillet or rump in the same marinade, adding a tablespoon of oil and a teaspoon of honey. Thread onto skewers or lay on a hot grill or griddle and cook for 1 to 2 minutes a side until charred. Serve over rice vermicelli with lettuce, cucumber, pickled carrot and daikon, bean sprouts, herbs, crushed peanuts, fried shallots and nuoc cham dressing.`],
      ['h3', `Nuoc cham dressing`],
      ['p', `Mix 3 tablespoons fish sauce, 3 tablespoons lime juice, 2 tablespoons sugar, 6 tablespoons warm water, 1 crushed garlic clove and 1 finely chopped chilli. Stir until the sugar dissolves. It should taste salty, sour, sweet and spicy all at once.`],
      ['h2', `Tips for great lemongrass beef`],
      ['ul', [
        `Chop the lemongrass very finely so it is fragrant, not chewy.`,
        `Marinate for at least 20 minutes, but not more than a few hours for thin slices.`,
        `Keep the wok or grill very hot so the sugar caramelises.`,
        `Cook in batches to avoid steaming the beef.`,
        `Finish with plenty of fresh herbs for brightness.`,
      ]],
      ['h2', `Serving ideas`],
      ['p', `Serve the stir-fry with jasmine rice and a simple cucumber salad, or in lettuce cups. The grilled beef is perfect in noodle bowls, rice paper rolls or a crusty banh mi roll with pickled vegetables, coriander and chilli. For a bigger Vietnamese meal, add [shaking beef](/blog/shaking-beef/) and a [Thai beef salad](/blog/thai-beef-salad/) to the table.`],
      ['h2', `Black Angus meat for sale: a premium option`],
      ['p', `If you are looking for Black Angus meat for sale, its fine marbling makes lemongrass beef even juicier, particularly when grilled. Our [Black Angus ribeye](/product/black-angus-beef-ribeye-steaks-mb3-4/) and [Angus rump](/product/angus-beef-rump-steaks-mb3-4/) are excellent sliced thinly for the grill.`],
      ['h2', `Beef and lemongrass questions`],
      ['h3', `Can I use lemongrass paste?`],
      ['p', `Yes. Jarred lemongrass paste is convenient; use about one tablespoon per stalk of fresh lemongrass. Check the label for added ingredients.`],
      ['h3', `What can I substitute for fish sauce?`],
      ['p', `Use extra soy sauce with a pinch of salt. The flavour will be different but still tasty.`],
      ['h3', `Is lemongrass beef spicy?`],
      ['p', `It is aromatic rather than hot. Add as much or as little chilli as you like.`],
      ['h2', `Building a Vietnamese noodle bowl`],
      ['p', `A vermicelli noodle bowl is the most popular way to serve grilled lemongrass beef in Vietnamese restaurants, and it is easy to set up at home. Soak or boil thin rice vermicelli until soft, rinse under cold water and drain well. Line each bowl with shredded lettuce, bean sprouts, cucumber matchsticks and plenty of mint, coriander and Thai basil. Add a nest of noodles, top with the hot grilled beef, then scatter with pickled carrot and daikon, crushed peanuts and fried shallots. Pour over nuoc cham at the table.`],
      ['p', `To make quick pickles, julienne a carrot and a small piece of daikon, sprinkle with a teaspoon of salt and leave for 10 minutes, then rinse and cover with equal parts vinegar, sugar and warm water. They are ready in 30 minutes and keep for a week in the fridge.`],
      ['p', `Leftover lemongrass beef keeps for two days in the fridge and is delicious cold in a noodle salad or tucked into a crusty roll with pickles and herbs.`],
      ['h2', `Buy halal beef online`],
      ['p', `Rump, flank, scotch fillet, chuck and Angus steaks are all in our [halal beef range](/shop/halal-beef/), certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('fried-rice-and-beef'),
    title: 'Fried Rice and Beef: Quick Wok Recipes With Mince or Steak',
    seoTitle: 'Fried Rice and Beef: Quick, Easy Recipes',
    excerpt: `Fried rice and beef done right: beef mince fried rice, a steak version, the day-old rice secret, wok tips and how to make fried rice minced beef taste great.`,
    body: [
      ['p', `Fried rice is the ultimate quick dinner: a few minutes in a hot wok turns leftover rice, a little beef, eggs and vegetables into a satisfying meal. Fried rice and beef is a particularly good pairing, whether you use mince for a budget-friendly family meal or thinly sliced steak for something more special. This guide shares two recipes, the secret to fluffy, separate grains, and tips to get restaurant-style flavour at home.`],
      ['h2', `The secret: day-old rice`],
      ['p', `Freshly cooked rice is soft and moist, so it clumps and turns mushy when fried. Rice that has been cooked, cooled and refrigerated overnight dries out slightly, and its starches firm up, so the grains separate and fry beautifully. If you need to use fresh rice, spread it on a tray and refrigerate it uncovered for an hour, or cook it with slightly less water. Long-grain jasmine rice is ideal.`],
      ['p', `Food safety note: cool cooked rice quickly (within an hour), refrigerate it promptly, and use it within a day or two. Reheat fried rice until steaming hot.`],
      ['h2', `Beef mince fried rice`],
      ['p', `This beef mince fried rice is fast, cheap and family-friendly. Serves four.`],
      ['ul', [
        `400 g beef mince`,
        `4 cups cooked, cold jasmine rice`,
        `3 eggs, beaten`,
        `1 onion, diced, and 3 cloves garlic, crushed`,
        `1 cup frozen peas and corn, and 1 carrot, diced`,
        `3 tablespoons soy sauce, 1 tablespoon oyster sauce and 1 teaspoon sesame oil`,
        `3 spring onions, sliced, and white pepper to taste`,
      ]],
      ['h3', `Method`],
      ['p', `Heat a wok over high heat with a tablespoon of oil. Pour in the eggs, scramble until just set, then remove. Add another tablespoon of oil and the mince; cook, breaking it up, until browned and slightly crisp. Remove. Add the onion, garlic and carrot and stir-fry for 2 minutes. Add the rice, breaking up any clumps, and stir-fry for 3 to 4 minutes until hot and starting to toast. Add the peas and corn, return the mince and egg, then add the soy, oyster sauce and sesame oil. Toss well, season with white pepper and finish with spring onion.`],
      ['h3', `Fried rice minced beef variations`],
      ['p', `For a spicy fried rice minced beef version, add a tablespoon of sambal or chilli paste with the garlic, or try Indonesian nasi goreng flavours with kecap manis, shallots and a fried egg on top. For a Thai-style version, add fish sauce, a little sugar and Thai basil at the end. Our [Asian beef mince recipes](/blog/asian-beef-mince-recipes/) have more ideas.`],
      ['h2', `Steak fried rice`],
      ['p', `For a more special fried rice, use 300 g of [rump](/product/rump-beef-steaks/) or [scotch fillet](/product/scotch-fillet-ribeye-steaks/). Slice thinly across the grain and toss with a teaspoon of soy and a teaspoon of cornflour. Sear the beef in a very hot wok for 1 minute, remove, and then continue with the recipe above, returning the beef with the egg at the end. Leftover cooked steak works too: dice it and add it in the final minute so it just warms through.`],
      ['h2', `Tips for restaurant-style fried rice`],
      ['ul', [
        `Use a very hot wok or the largest heavy pan you have.`,
        `Do not overcrowd: cook in two batches for large quantities.`,
        `Break up cold rice with your hands before adding it to the pan.`,
        `Add soy sauce around the edge of the hot wok so it sizzles and caramelises.`,
        `Season with white pepper, which gives the classic Chinese takeaway flavour.`,
      ]],
      ['h2', `Beef bone broth for better rice`],
      ['p', `For extra depth, cook the rice for your fried rice in beef stock instead of water. A homemade stock from a beef bone or two adds richness and body. Our [beef bones for soup](/product/beef-bones-for-soup/) and [marrow bones](/product/beef-marrow-bones/) make excellent stock, and our guide to the [best bones for bone broth](/blog/best-bones-for-bone-broth/) explains how.`],
      ['h2', `Try buffalo mince`],
      ['p', `If you have been searching buffalo meat near me, water buffalo mince is a lean, flavourful alternative to beef in fried rice. It cooks the same way and has a slightly sweeter, richer taste. Our [buffalo mince](/product/buffalo-mince/) is in our [buffalo meat range](/shop/buffalo-meat/).`],
      ['h2', `Serving ideas`],
      ['p', `Serve fried rice on its own as a quick meal, topped with a fried egg, or as a side for [Mongolian beef](/blog/mongolian-beef-slow-cooker/), [beef and black bean](/blog/beef-and-black-bean/) or [satay beef](/blog/satay-beef/). Add a crunchy cucumber salad or some steamed greens to round it out.`],
      ['h2', `Fried rice questions`],
      ['h3', `Can I make fried rice with brown rice?`],
      ['p', `Yes. Cooled brown rice fries well and adds a nutty flavour. Cook it slightly firmer than usual.`],
      ['h3', `Why is my fried rice soggy?`],
      ['p', `The rice was too fresh, the pan was not hot enough, or there was too much sauce. Use day-old rice, cook over high heat and add sauces sparingly.`],
      ['h3', `How long does fried rice keep?`],
      ['p', `Up to two days in the fridge. Reheat thoroughly until steaming hot.`],
      ['h2', `Cleaning out the fridge`],
      ['p', `Fried rice is the perfect way to use leftovers. Diced roast vegetables, a handful of spinach, half a capsicum, some mushrooms or leftover cooked beef can all go in. Add harder vegetables early so they soften, and leafy greens at the end so they just wilt. Leftover roast beef, braised brisket or pulled beef add instant flavour; dice or shred them and stir them through at the end until hot.`],
      ['p', `Fried rice is also a great make-ahead lunch. Pack it into containers once cool, refrigerate, and reheat until steaming hot the next day.`],
      ['h2', `Fried rice from around Asia`],
      ['p', `Almost every Asian cuisine has its own fried rice. Chinese yangzhou fried rice combines egg, spring onion and diced meat; Indonesian nasi goreng uses kecap manis, shallots and sambal and is topped with a fried egg; Thai khao pad adds fish sauce, tomato and lime; and Korean kimchi fried rice is spicy, tangy and often finished with cheese. Japanese cooks make omurice by wrapping ketchup-flavoured fried rice in an omelette. All of these work beautifully with beef, so try a different style each week.`],
      ['h2', `Buy halal beef online`],
      ['p', `Beef mince, rump, scotch fillet and buffalo mince are all available from our [halal beef range](/shop/halal-beef/) and buffalo range. Every product is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia.`],
    ],
  },
  {
    ...meta('asian-beef-mince-recipes'),
    title: 'Asian Beef Mince Recipes: Six Quick Weeknight Dinners',
    seoTitle: 'Asian Beef Mince Recipes: 6 Quick Dinners',
    excerpt: `Six Asian beef mince recipes for busy nights: Thai larb, Korean beef bowls, san choy bow, keema, dan dan noodles and Chinese mince with green beans.`,
    body: [
      ['p', `Beef mince is one of the most versatile ingredients in the kitchen, and Asian cooking shows it off brilliantly. With a few pantry staples, such as soy sauce, garlic, ginger, chilli and fresh herbs, a packet of mince becomes a fragrant, satisfying dinner in 20 to 30 minutes. This collection of Asian beef mince recipes covers six favourites from across the region, all quick, budget-friendly and family-friendly.`],
      ['h2', `Choosing your mince`],
      ['p', `For most Asian mince dishes, a mince with some fat gives the best flavour and browning. Our [premium beef mince](/product/premium-beef-mince/) is a great all-rounder, while [extra lean beef mince](/product/extra-lean-beef-mince/) suits lighter dishes such as larb and lettuce cups. Brown the mince well over high heat, without stirring too often, to develop rich, caramelised flavour.`],
      ['h2', `1. Thai-style beef larb`],
      ['p', `Larb is a fresh, zingy minced meat salad from Laos and northern Thailand. Brown 500 g lean beef mince in a little oil, breaking it into small pieces. Remove from the heat and stir in 3 tablespoons lime juice, 2 tablespoons fish sauce, 1 teaspoon sugar, 1 to 2 chopped chillies, 2 thinly sliced shallots, a large handful of mint and coriander, and 2 tablespoons toasted rice powder (see our [Thai beef salad](/blog/thai-beef-salad/) for how to make it). Serve warm with lettuce leaves, cucumber and sticky rice.`],
      ['h2', `2. Korean beef rice bowls`],
      ['p', `Brown 500 g beef mince with 3 cloves of garlic and a tablespoon of grated ginger. Add 1/4 cup soy sauce, 2 tablespoons brown sugar, 1 teaspoon sesame oil and a pinch of chilli flakes, and simmer for 2 to 3 minutes until glossy. Serve over rice with steamed broccoli, kimchi, sliced cucumber, a fried egg, spring onion and toasted sesame seeds.`],
      ['h2', `3. San choy bow (lettuce cups)`],
      ['p', `Stir-fry 500 g beef mince with garlic, ginger and diced water chestnuts or carrot. Add 2 tablespoons oyster sauce, 1 tablespoon soy, a splash of water and a teaspoon of sesame oil, and toss until glossy. Spoon into crisp iceberg lettuce cups and top with spring onion, crushed peanuts and fried shallots. It is light, crunchy and a hit with children.`],
      ['h2', `4. Keema (spiced mince with peas)`],
      ['p', `Keema is a South Asian favourite. Fry a diced onion until golden, add garlic, ginger and green chilli, then a teaspoon each of cumin, coriander and garam masala, and half a teaspoon each of turmeric and chilli powder. Add 500 g beef mince and brown it, then a chopped tomato and half a cup of water. Simmer for 15 minutes, add a cup of frozen peas for the last 5 minutes, and finish with coriander. Serve with rice, roti or paratha.`],
      ['h2', `5. Dan dan-style noodles`],
      ['p', `Stir-fry 400 g beef mince until crisp, then add a tablespoon of chilli bean paste (check the label), 2 tablespoons soy sauce, a teaspoon of sugar and a pinch of ground Sichuan pepper. Toss through cooked wheat noodles with a sauce of tahini or peanut butter, soy, chilli oil, black vinegar and a little noodle water. Top with spring onion and blanched greens. It is rich, nutty and numbing-spicy.`],
      ['h2', `6. Chinese mince with green beans`],
      ['p', `This simple stir-fry pairs crisp-fried mince with blistered green beans. Fry 300 g trimmed green beans in hot oil until wrinkled and blistered, then remove. Stir-fry 400 g beef mince with garlic, ginger and chilli until crisp. Return the beans, add 2 tablespoons soy sauce, a tablespoon of oyster sauce and a pinch of sugar, and toss well. Serve with rice.`],
      ['h2', `Asian mince beef recipes tips`],
      ['ul', [
        `Brown the mince in batches over high heat; overcrowding makes it steam and turn grey.`,
        `Add aromatics such as garlic, ginger and chilli after the mince has browned so they do not burn.`,
        `Balance every dish: salty (soy or fish sauce), sweet (sugar), sour (lime or vinegar) and hot (chilli).`,
        `Finish with fresh herbs, spring onion or crunchy toppings for contrast.`,
        `Most of these dishes reheat well, so cook extra for lunches.`,
      ]],
      ['h2', `Slow-cooked Asian beef: best cut of beef for crock pot`],
      ['p', `When you have more time, slow-cooked Asian-style beef is equally delicious. The best cut of beef for crock pot cooking is chuck: it becomes meltingly tender in a soy, ginger and star anise braise. Our [Mongolian beef slow cooker](/blog/mongolian-beef-slow-cooker/) recipe is a great place to start.`],
      ['h2', `Buffalo meat for sale: a leaner alternative`],
      ['p', `Looking for buffalo meat for sale? Water buffalo mince is a lean, slightly sweet alternative to beef in all of these recipes. It browns well and works especially nicely in larb and lettuce cups. Find [buffalo mince](/product/buffalo-mince/) in our [buffalo meat range](/shop/buffalo-meat/).`],
      ['h2', `Asian beef mince questions`],
      ['h3', `Can I freeze cooked mince dishes?`],
      ['p', `Yes. Keema, Korean beef and Chinese-style mince all freeze well for up to three months. Larb and lettuce cups are best eaten fresh.`],
      ['h3', `How can I make these dishes milder for children?`],
      ['p', `Leave out the chilli and serve it on the side. Korean beef bowls and san choy bow are naturally mild and very kid-friendly.`],
      ['h3', `Which rice is best?`],
      ['p', `Jasmine rice suits most Thai, Chinese and Vietnamese dishes. Short-grain rice works for Korean bowls, and basmati is perfect with keema.`],
      ['h2', `Pantry staples for Asian mince dishes`],
      ['p', `Keep a few staples on hand and you can make any of these dishes at short notice: light and dark soy sauce, oyster sauce, fish sauce, sesame oil, rice vinegar, chilli paste or sambal, garlic, ginger, spring onions and a bag of jasmine rice. Fresh herbs such as coriander, mint and Thai basil add brightness; they keep longer wrapped in damp paper towel in the fridge. With these in the cupboard and a pack of mince in the freezer, dinner is never more than half an hour away.`],
      ['p', `Rotate through these six recipes and you will have a different Asian-inspired dinner every night of the week.`],
      ['h2', `Buy halal beef mince online`],
      ['p', `Premium and extra lean beef mince, plus buffalo and lamb mince, are all available in our [halal beef range](/shop/halal-beef/) and wider shop. Everything is certified halal by Halal Control Australia and delivered chilled from Greenacre, Sydney, to anywhere in Australia. For more quick ideas, see our [30 minute beef mince recipes](/blog/30-minute-beef-mince-recipes/).`],
    ],
  },
]
